"""Generate HFS BMP normalization data from Python's frozen Unicode 3.2 DB."""
from pathlib import Path
from unicodedata import ucd_3_2_0 as ucd


def excluded(r):
    return 0x2000 <= r <= 0x2FFF or 0xF900 <= r <= 0xFAFF


def decompose(r):
    if excluded(r):
        return [r]
    mapping = ucd.decomposition(chr(r))
    if not mapping or mapping.startswith("<"):
        return [r]
    return [c for part in mapping.split() for c in decompose(int(part, 16))]


lines = [
    "// Code generated by gen_unicode.py using Unicode 3.2.0; DO NOT EDIT.",
    "// HFS exclusions: https://developer.apple.com/library/archive/technotes/tn/tn1150.html",
    "package hfsplus",
    "",
    "var hfsDecompositions = map[rune]string{",
]
# HFS normalizes UTF-16 code units, leaving supplementary characters unchanged.
for r in range(0x10000):
    if 0xAC00 <= r <= 0xD7A3:
        continue  # Hangul is decomposed algorithmically.
    parts = decompose(r)
    if parts != [r]:
        value = "".join(f"\\u{c:04x}" if c <= 0xFFFF else f"\\U{c:08x}" for c in parts)
        lines.append(f'\t0x{r:04X}: "{value}",')
lines += ["}", "", "var hfsCombiningClasses = map[rune]uint8{"]
for r in range(0x10000):
    c = ucd.combining(chr(r))
    if c:
        lines.append(f"\t0x{r:04X}: {c},")
lines += ["}", ""]
Path(__file__).with_name("unicode_tables.go").write_text("\n".join(lines))
